ncies (#566)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"649c76f3943a75929ea288b3d0e67c6e11a4f207\",\"date\":\"2026-05-28T18:53:53-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#565)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"4a542bb184620adf4a130a72da5bd5ddc0b944a4\",\"date\":\"2026-05-28T20:17:17+05:30\",\"message\":\"(fix) O3-5703: Prevent \\\"Select source type\\\" label from wrapping in stock sources toolbar (#562)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Bawantha Thilan\",\"authorEmail\":\"38850236+Bawanthathilan@users.noreply.github.com\"},{\"hash\":\"1673d8bb67d7658709216cd15f0543aa459a765c\",\"date\":\"2026-05-26T12:58:05-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#564)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"dfcf279b9baddabb123c9486f26267412e862ac9\",\"date\":\"2026-05-26T12:17:28-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#563)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"0477b5663b21e6d7df9f39148b7b5ef5b2075305\",\"date\":\"2026-05-26T02:27:18+05:30\",\"message\":\"(chore) Migrate CI to reusable GHA workflows (#559)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Nethmi Rodrigo\",\"authorEmail\":\"nethmi@openmrs.org\"},{\"hash\":\"45a3588947e9c3110d925eec8295fd4ba64ceefb\",\"date\":\"2026-05-22T17:43:25-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#561)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"57dc1389ee8dc400b91d277298ce0eec80f335b6\",\"date\":\"2026-05-22T16:19:33-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#560)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"ff657d98c23604ff98d0c558e9cffa1db654d007\",\"date\":\"2026-05-21T09:44:11-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#558)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"2ed9871491ea1a4ae0daf80ccb55e209a3018104\",\"date\":\"2026-05-20T17:18:51-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#557)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"ea20ebe76abe40e54f285d09bfcae04628328b9e\",\"date\":\"2026-05-17T17:28:19-04:00\",\"message\":\"(chore) Update translations from Transifex (#556)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"c9d7c101c64554474c6b32c734789362166eaf37\",\"date\":\"2026-05-17T20:28:02+03:00\",\"message\":\"(fix) O3-5648: Wire up stock report submission and add missing patient/stock-item inputs (#542)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Lubwama Samuel\",\"authorEmail\":\"lubwamasamuel3@gmail.com\"},{\"hash\":\"03afee52e4b4905ea835986a4389e7968ed963d4\",\"date\":\"2026-05-13T17:07:57-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#555)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"65e856c0f7419e9995ceeafda502adf102791d26\",\"date\":\"2026-05-13T22:49:15+03:00\",\"message\":\"(chore) Raise vitest testTimeout to 30s (#554)\",\"refs\":\"\",\"body\":\"The default 5s per-test timeout fires on CI for the StockItemsTable\\n'renders initial state and UI elements correctly' test, which is a\\nuserEvent-heavy test that completes in well under a second locally\\nbut takes ~6s on GitHub Actions runners.\\n\\nThe local-vs-CI gap is vitest's per-test overhead (ESM resolution and\\nSWC transforms) combined with slower CI hardware. The same pattern\\nshowed up across openmrs-esm-patient-chart and was addressed there\\nwith the same global bump.\\n\\nRaise testTimeout to 30s. Real hangs will still fail loudly; this\\nonly forgives slow-but-progressing tests.\\n\\nSee https://github.com/openmrs/openmrs-esm-stock-management/actions/runs/25805834552/job/75808178552\\nfor the failing run.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"1b6d419503165d7ca514c53dbe87ac1f256cf725\",\"date\":\"2026-05-13T17:32:40+03:00\",\"message\":\"(chore) Migrate to rspack (#553)\",\"refs\":\"\",\"body\":\"Switch the bundler from webpack to rspack, matching the migration already\\nlanded across the rest of the distro.\\n\\n- Rename webpack.config.js to rspack.config.js and require\\n  openmrs/default-rspack-config\\n- Update package.json build/serve/analyze scripts to call rspack\\n- Drop @types/webpack-env and declare RequireContext + NodeJS.Require\\n  locally in declarations.d.ts so require.context still type-checks\\n- Drop the **/*.d.ts entry from .eslintignore (deleting the now-empty\\n  file) so the lint-staged eslint pass (which uses --max-warnings 0)\\n  does not flag declarations.d.ts as ignored. The file lints cleanly.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"79953cf66885a70e1b0430f14d82d9fb8b4de86e\",\"date\":\"2026-05-13T16:45:28+03:00\",\"message\":\"(chore) Migrate from jest to vitest (#552)\",\"refs\":\"\",\"body\":\"* (chore) Migrate from jest to vitest\\n\\nSwap the test runner from jest to vitest, aligning stock-management\\nwith the patterns adopted by openmrs-esm-core, openmrs-esm-billing-app,\\nand the other in-flight migrations.\\n\\n- Replace jest, @swc/jest, jest-cli, jest-environment-jsdom, and\\n  @types/jest with vitest, @vitest/coverage-v8, jsdom, and cross-env;\\n  bump @testing-library/dom (10.4.0 to 10.4.1) and\\n  @testing-library/jest-dom (5.x to 6.x) so the /vitest subpath is\\n  available.\\n- Add vitest.config.ts with the standard O3 vitest setup: jsdom\\n  environment, .scss/.css aliased to identity-obj-proxy with an\\n  anchored ^.*.s?css$ regex, @openmrs/esm-framework aliased to its\\n  mock, react-i18next aliased to the local __mocks__ file, @mocks\\n  and @tools aliases for the path shortcuts already in use, and\\n  fakeTimers.toFake limited to the timers we actually fake (excludes\\n  queueMicrotask which otherwise breaks React's scheduler).\\n- Add tools/setup-tests.ts to load @testing-library/jest-dom/vitest\\n  (which is enough for tsc to pick up the matcher type extension),\\n  register afterEach(cleanup), and rewrite the ResizeObserver mock\\n  as a class (Carbon's TextArea calls it with `new`).\\n- Convert the eighteen test files to the vitest API: explicit imports\\n  for describe/expect/it/test/vi (plus beforeEach where used), jest.*\\n  swapped for vi.*, jest.Mock type alias replaced with Mock from\\n  vitest. Inline component factories of the form vi.mock(name, () =>\\n  () => <jsx />) wrapped in { default: ... } since vitest requires\\n  the factory to return a module object. The vi.mock('./hooks/\\n  useParties', () => vi.fn()) factory similarly wrapped to expose a\\n  default export.\\n- Update the danger-button selector in stock-sources-delete.test.tsx\\n  to /danger\\\\s*delete/i: the newer testing-library no longer joins\\n  the visually-hidden \\\"danger\\\" prefix and the visible \\\"Delete\\\" with\\n  a space when computing the accessible name.\\n- Delete jest.config.js.\\n\\nAll 112 tests pass; lint and typescript checks are green.\\n\\n* (chore) Tidy up vitest config and test imports\\n\\nFollow-ups to the jest→vitest migration:\\n\\n- vitest.config.ts: drop `globals: true` (every test file imports\\n  describe/it/expect/vi/test explicitly, so the global is dead),\\n  drop the unused `@tools` alias (no `from '@tools'` in src), and\\n  add `resolve.mainFields: ['module', 'main']` so vitest picks\\n  @carbon/react's ESM entry. The CJS entry's `var l10n =\\n  require('flatpickr/dist/l10n/index')` only exposes `default`,\\n  leaving `l10n['en']` undefined and producing 300+ \\\"flatpickr:\\n  invalid locale undefined\\\" stderr lines per `--reporter=verbose`\\n  run.\\n- 10 test files: strip the unused `test` named import from the\\n  `vitest` import line. ESLint won't catch these because\\n  `@typescript-eslint/no-unused-vars` is disabled in .eslintrc.\\n- 3 test files (step1, user-selector, stock-sources-items-table):\\n  drop redundant `__esModule: true` from `vi.mock` factory\\n  returns — vitest doesn't need the marker when the factory\\n  returns `{ default: ... }`.\\n\\n* (fix) Silence React warnings from stock-item-details\\n\\nTwo pre-existing warnings surfaced once vitest started routing\\nper-test stderr through its verbose reporter:\\n\\n1. `forwardRef render functions accept exactly two parameters` —\\n   StockItemDetails was wrapped in forwardRef but its render\\n   function only took `(props)` and no caller passed a ref. Drop\\n   the dead wrap and inline-type the props.\\n\\n2. `React does not recognize the 'controllerName' prop on a DOM\\n   element` — ControlledTextInput spread `{...props}` onto the\\n   inner Carbon `<TextInput>`, leaking the `controllerName` and\\n   `control` react-hook-form props through to the DOM `<input>`.\\n   Destructure them out before spreading. The sibling\\n   ControlledRadioButtonGroup already does this; the wrappers\\n   now agree.\\n\\n* (chore) Use fileURLToPath for vitest config aliases\\n\\nvitest.config.ts used new URL(...).pathname for the react-i18next\\nand @mocks alias replacements. On Windows .pathname yields /C:/...\\nwhich is not a valid filesystem path, so Vite's resolver fails.\\nAdd a small fileURLToPath helper and route every URL-based path\\nthrough it, matching the pattern adopted in openmrs-esm-form-builder.\",\"authorName\":\"Dennis Kigen\",\"authorEmail\":\"kigen.work@gmail.com\"},{\"hash\":\"7005894f41019c10e83a501bc770221c9187fcc9\",\"date\":\"2026-05-11T19:30:31-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#551)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"f402545008a3b2f37fca4e04e1ceead21c194dbd\",\"date\":\"2026-05-08T15:53:17-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#550)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"4f08666b410e7392b54054cd947e4dad2f55f259\",\"date\":\"2026-05-08T13:51:56-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#549)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"51a03be863fb664ba49356745e6497f9209b4eb4\",\"date\":\"2026-05-07T17:31:16-04:00\",\"message\":\"(chore) Update translations from Transifex (#548)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"d030fe9c64421ed40aa09c172bfe2e7630828407\",\"date\":\"2026-05-07T15:13:37-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#547)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"6ea904ad3ba59b17d8366d5cc3283f8968d416be\",\"date\":\"2026-05-07T22:00:44+05:30\",\"message\":\"fix(O3-5563): require purchase price packaging unit when purchase price is set (#528)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Kavitha Kanchana\",\"authorEmail\":\"146015143+kanchana404@users.noreply.github.com\"},{\"hash\":\"2a4dbe17937b60e59174c4724ace9b559781eae1\",\"date\":\"2026-05-06T17:41:10-04:00\",\"message\":\"(chore) Update translations from Transifex (#546)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"a6493ac0357dab2c49ebb541b04254e96259aef4\",\"date\":\"2026-05-06T15:11:06-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#545)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"a1868e4282a38a25cd821a012f2df6ab15d0e62d\",\"date\":\"2026-05-06T13:00:30-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#544)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"6a50b7269b5073580f53eff29b3215f528fe217e\",\"date\":\"2026-05-05T17:36:30-04:00\",\"message\":\"(chore) Update translations from Transifex (#543)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"d9e7c5c49d29b5b1dc37951adb3c2887916e4f48\",\"date\":\"2026-05-05T15:10:51+05:30\",\"message\":\"(fix) O3-5562: Edit Items panel fields don't update when selecting a different stock item (#514)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"Wikum Weerakutti\",\"authorEmail\":\"wikum@linuxdeveloper.space\"},{\"hash\":\"c67e47060f34697bd5e9aa63389a35fc5df2eed8\",\"date\":\"2026-05-05T09:15:40+03:00\",\"message\":\"(fix) O3-5647: Fix User Role Scope Save Functionality (#541)\",\"refs\":\"\",\"body\":\"* O3-5647: Fix User Role Scope Save Functionality\\n\\n* Response to Comments\",\"authorName\":\"Lubwama Samuel\",\"authorEmail\":\"lubwamasamuel3@gmail.com\"},{\"hash\":\"19d5c414c019b9e1434f2a6fe6517cc42c724f7a\",\"date\":\"2026-05-01T10:00:16-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#540)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"fbdf1ec3e50b35e159988bb3c00726d1151142d6\",\"date\":\"2026-04-24T15:27:53-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#539)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"59a6a3a6b49f91ddaa60c60ce36768692b01d4ae\",\"date\":\"2026-04-22T15:47:13-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#537)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"f4310adb6032aba85870119dd480cab377089300\",\"date\":\"2026-04-21T10:15:45-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#536)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"abde50f42fabf5b38220df5639e943b9c8180a2f\",\"date\":\"2026-04-18T09:42:49-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#535)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"1124e69c9d20e8d4e018561c95934fa66deef5dd\",\"date\":\"2026-04-18T07:57:15-04:00\",\"message\":\"(chore) Update OpenMRS dependencies (#534)\",\"refs\":\"\",\"body\":\"\",\"authorName\":\"openmrs-bot\",\"authorEmail\":\"infrastructure@openmrs.org\"},{\"hash\":\"91a6af5cdb94d51894975648f75dc7d805701a02\",\"date\":\"2026-04-18T12:53:08+03:00\",\"message\":\"(chore) Update OpenMRS dependencies\",\"refs\":\"\",\"body\":\"Bumps @openmrs/esm-framework, @openmrs/esm-styleguide, and openmrs to\\n9.0.3-pre.4550. The new framework's dist/index.d.ts re-exports from\\n@openmrs/esm-globals/src/public, which under classic \\\"node\\\" module\\nresolution resolves to the source .ts file. That file redeclares\\n__webpack_share_scopes__, conflicting with the declaration in\\nesm-globals/dist/types.d.ts and breaking `yarn typescript`.\\n\\nSwitch moduleResolution to \\\"bundler\\\" so the exports map is honored and\\nthe subpath resolves to dist/public.d.ts. Mirrors the fix applied in\\nopenmrs-esm-patient-chart#3235.\\n\",\"authorName\":\"denniskigen\",\"authorEmail\":\"kigen.work@gmail.com\"}],\"totalCount\":160}"}],"tool_result_meta":[{"id":"toolu_01LW66zNjknvPkRxK31UQVyT","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
